def prose_spacing(s):
 # Unit/abbreviation spacing improves authored prose without touching IDs or sources.
 s=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',s)
 s=re.sub(r'(\d+) d (\d+)',r'\1d\2',s)
 return s
for row in P:
 for key in ['procedure','newChoices']:row[key]=prose_spacing(row[key])
 row['workedCases']=[prose_spacing(x) for x in row['workedCases']]

